"""2D story chapters (ch3, ch5, ch9): left column = scenes of words timed to the voice (words_raghav_v3.json, chapter-relative),
right = the illustrated brain (brain_kit.html) animated by the same timeline. usage: python -I make_story.py"""
import json

HEAD = '''<!doctype html>
<html>
<head>
<meta charset="utf-8">
<script src="https://cdn.jsdelivr.net/npm/gsap@3.15.0/dist/gsap.min.js"></script>
<style>
  /* GENERATED by make_story.py (ch__CH__). charcoal-gold/dark: GOLD ONLY on the one key word per frame; video type sizes
     (display >= 72, lines >= 48, labels >= 30). Words in the left column (x 136-776), the illustrated brain on the right.
     Vessel dots/colours are the anatomy's own (orange = scalp artery, cyan = brain arteries) - the documented exception. */
  :root { --dark:#1C1C1C; --gold:#F5B700; --cream:#FFF8E6; --edge:rgba(255,248,230,0.35); }
  body { margin:0; }
  #root { position:relative; width:1920px; height:1080px; overflow:hidden; background:var(--dark);
          font-family:'Space Grotesk','Hind',sans-serif; color:var(--cream); }
  .note { position:absolute; left:136px; top:96px; font:italic 500 30px 'Space Grotesk','Hind',sans-serif; opacity:0.75; }
  .grp { position:absolute; left:136px; top:190px; width:640px; display:flex; flex-direction:column; align-items:flex-start; gap:22px; }
  .lab  { font:600 30px 'Space Grotesk','Hind',sans-serif; letter-spacing:0.18em; opacity:0.7; }
  .big  { font:700 128px/1 'Space Grotesk','Hind',sans-serif; letter-spacing:-0.02em; }
  .big2 { font:700 88px/1.02 'Space Grotesk','Hind',sans-serif; letter-spacing:-0.01em; }
  .line { font:600 52px/1.15 'Space Grotesk','Hind',sans-serif; text-wrap:balance; }
  .chip { padding:14px 26px; border-radius:14px; background:rgba(28,28,28,0.86); border:2px solid var(--edge);
          font:600 44px/1.2 'Space Grotesk','Hind',sans-serif; }
  .row  { display:flex; gap:16px; flex-wrap:wrap; }
  .gold { color:var(--gold); }
  .dim  { opacity:0.55; }
  .dot  { display:inline-block; width:30px; height:30px; border-radius:15px; margin-right:14px; vertical-align:-3px; }
  #kit { position:absolute; __KITBOX__ }
  #disc { position:absolute; left:136px; bottom:96px; font:500 30px/1.3 'Space Grotesk','Hind',sans-serif; opacity:0.7; width:640px; }
</style>
</head>
<body>
<div id="root" data-composition-id="ch__CH__" data-start="0" data-duration="__DUR__" data-width="1920" data-height="1080">
  <!--PLATE-->
  <div class="note" id="note">2D illustration</div>
  <div id="kit"></div>
__GROUPS__
__EXTRA_HTML__
</div>
<!--BRAINKIT-->
<script>
  // Chapter-relative word times from words_raghav_v3.json (ch__CH__ starts at __START__ s of master v3). ONE entrance for every
  // block: rise 24 px, 0.5 s, power3.out; exits 0.4 s. The illustrated brain animates on the same timeline.
  const tl = gsap.timeline({ paused: true });
  const inn = (sel, t) => tl.fromTo(sel, { autoAlpha: 0, y: 24 }, { autoAlpha: 1, y: 0, duration: 0.5, ease: 'power3.out' }, t);
  const out = (sel, t) => tl.to(sel, { autoAlpha: 0, duration: 0.4, ease: 'power2.in' }, t);
  gsap.set('#note', { autoAlpha: 0 }); tl.to('#note', { autoAlpha: 0.75, duration: 0.6 }, 0.2);
  const B = BrainKit('#kit', __KITOPTS__);
__SCRIPT__
  out('#note', __DUR__ - 0.5);
  const upd = t => B.update(t);
  window.addEventListener('hf-seek', e => upd(e.detail.time));
  tl.eventCallback('onUpdate', () => upd(tl.time()));
  upd(0);
  window.__timelines = { ch__CH__: tl };
</script>
</body>
</html>
'''


def build(ch, dur, start, groups, script, kit_box, kit_opts, extra_html=''):
    gh = []
    js = []
    for gi, g in enumerate(groups):
        gid = f'g{gi}'
        items = ''.join(f'<div class="{it["cls"]}" id="{gid}_{ii}">{it["html"]}</div>' for ii, it in enumerate(g['items']))
        gh.append(f'  <div class="grp" id="{gid}" style="{g.get("style", "")}">{items}</div>')
        js.append(f"  gsap.set('#{gid}', {{ autoAlpha: 1 }}); gsap.set('#{gid} > div', {{ autoAlpha: 0 }});")
        for ii, it in enumerate(g['items']):
            js.append(f"  inn('#{gid}_{ii}', {it['t']});")
        js.append(f"  out('#{gid} > div', {g['out']});")
    page = HEAD
    for k, v in {'__CH__': str(ch), '__DUR__': str(dur), '__START__': str(start), '__KITBOX__': kit_box, '__KITOPTS__': json.dumps(kit_opts),
                 '__GROUPS__': '\n'.join(gh), '__EXTRA_HTML__': extra_html, '__SCRIPT__': '\n'.join(js) + '\n' + script}.items():
        page = page.replace(k, v)
    open(f'overlay_ch{ch}.html', 'w', encoding='utf-8').write(page)
    print(f'overlay_ch{ch}.html', len(page))


