# ---------------------------------------------------------------- ch5  The reveal: two arteries (31.56 s)
build(5, 31.56, 120.197, [
    {'out': 4.05, 'items': [{'t': 0.06, 'cls': 'big2', 'html': 'But <span class="gold">a catch</span>'},
                           {'t': 1.5, 'cls': 'line', 'html': 'An artery right under Temple'}]},
    {'out': 12.6, 'items': [{'t': 4.1, 'cls': 'lab', 'html': '<span class="dot" style="background:#FF7A2F"></span>SCALP ARTERY'},
                            {'t': 4.14, 'cls': 'line', 'html': 'Superficial temporal artery'},
                            {'t': 7.15, 'cls': 'lab', 'html': 'A BRANCH OF THE EXTERNAL CAROTID'},
                            {'t': 9.15, 'cls': 'line', 'html': 'It feeds the <span class="gold">skin</span>, face and scalp'}]},
    {'out': 20.9, 'items': [{'t': 12.9, 'cls': 'lab', 'html': '<span class="dot" style="background:#2EE6FF"></span>BRAIN ARTERIES'},
                            {'t': 12.95, 'cls': 'line', 'html': 'Your brain is fed by a <span class="gold">different route</span>'},
                            {'t': 16.2, 'cls': 'chip', 'html': 'Internal carotid'}, {'t': 17.3, 'cls': 'chip', 'html': 'Vertebral arteries'},
                            {'t': 18.8, 'cls': 'lab', 'html': 'DEEP INSIDE THE SKULL'}]},
    {'out': 24.9, 'items': [{'t': 21.1, 'cls': 'big2', 'html': '<span class="gold">Two</span> separate systems'},
                            {'t': 22.75, 'cls': 'line', 'html': 'with separate control'}]},
    {'out': 31.1, 'items': [{'t': 25.05, 'cls': 'lab', 'html': 'SO THE REAL QUESTION IS NOT'},
                            {'t': 25.9, 'cls': 'line', 'html': 'does Temple measure blood flow?'},
                            {'t': 28.9, 'cls': 'lab', 'html': 'IT IS'},
                            {'t': 29.3, 'cls': 'big', 'html': '<span class="gold">Whose</span> blood?'}]},
], '''  // the scalp artery (orange) and the brain's own arteries (cyan) are told apart by colour, as in the colour code
  B.vessels.forEach((v, i) => { gsap.set(v, { attr: { stroke: '#2EE6FF' }, opacity: 0.0 }); });
  gsap.set(B.scalp, { opacity: 0 });
  B.drawOn(tl, 0.2, 2.0);
  tl.to(B.scalp, { opacity: 1, duration: 0.6 }, 1.5);                  // "ठीक नीचे एक आर्टरी": the orange scalp artery under the device
  tl.to(B.scalp, { attr: { 'stroke-width': 9 }, duration: 0.5, yoyo: true, repeat: 5 }, 4.14);
  B.flowScalp(4.2, 12.4, { period: 0.9, colors: ['#FF7A2F'] });
  B.vessels.forEach(v => tl.to(v, { opacity: 0.85, duration: 0.8 }, 12.95));            // "आपके दिमाग़ को ख़ून ... अलग रास्ते": the cyan brain arteries
  B.flow(13.2, 20.8, { period: 0.9, colors: ['#2EE6FF'] });
  tl.to(B.scalp, { opacity: 0.4, duration: 0.5 }, 21.1);
  B.vessels.forEach(v => tl.to(v, { opacity: 1, duration: 0.3 }, 21.1));
  tl.to(B.scalp, { opacity: 1, duration: 0.5 }, 21.5);                 // both at once: two systems
  out('#kit', 31.1);
''', 'left:1000px; top:150px; width:760px; height:712px;', {'device': True})

